"""
Jobbergate-core contains key components that are shared among sub-projects.
"""

try:
    from jobbergate_core._version import __version__
except ModuleNotFoundError:
    # _version.py is generated by hatch-vcs at build time, so it is missing when the
    # source tree is bind-mounted over the installed package (e.g. jobbergate-composed):
    # fall back to the metadata of the distribution installed at image build time
    from importlib.metadata import PackageNotFoundError, version

    try:
        __version__ = version("jobbergate-core")
    except PackageNotFoundError:  # running straight from a source checkout
        __version__ = "0.0.0"

from jobbergate_core.auth import AuthenticationError, JobbergateAuthHandler, TokenError

__all__ = [
    "__version__",
    "AuthenticationError",
    "JobbergateAuthHandler",
    "TokenError",
]
